from robot.utils.robottime import timestr_to_secs

from .base import BaseInterface
from ..validators import IsString, IsOneOf
from ..converter import to_bool
from ..util import save_disconnect_logs


class BasicProceduresInterface(BaseInterface):

    def block(self, dist_name, timeout=60, alias="default"):
        """Perform block procedure.

        :param string dist_name: block target object dist_name.
                                 Possible distanmes available in
                                 http://cebula.emea.nsn-net.net:8888/spec/admin-spec/wikis/admin-api-block-unblock
                                 From SBTS17A onwards it is recommended to use runtime view dist name
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(dist_name)
        self.store.get(alias).execute_procedure("block", {"distName": dist_name}, timeout)

    def unblock(self, dist_name, timeout=60, alias="default"):
        """Preform unblock procedure.

        :param string dist_name: unblock target object dist_name.
                                 From SBTS17A onwards it is recommended to use runtime view dist name
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(dist_name)
        self.store.get(alias).execute_procedure("unblock", {"distName": dist_name}, timeout)

    def collect_snapshot(
            self, target_file_name, coverage="Full", force=True, regexp_filter=None,
            reason=None, cells=None, timeout=360, alias="default"):
        """Collect Techrep snapshot.

        :param string target_file_name: target snapshot filename.
        :param string coverage: Snapshot coverage (Full, Minor or HealthCheck)
        :param bool force: Force snapshot collection
        :param string filter: Snapshot filtering regexp (Optional)
        :param string reason: Snapshot reason (Optional)
        :param string cells: Comma-separated cell dist names (Optional)
        :param float timeout: Time to wait for positive procedure result
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        force = to_bool(force)
        IsString().check(target_file_name)
        IsString().check(coverage)
        coverage = coverage.title()
        if coverage == "Healthcheck":
            coverage = "HealthCheck"
        IsOneOf("Full", "Minor", "HealthCheck").check(coverage)

        parameters = {
            "coverage": coverage,
            "force": "Yes" if force else "No",
        }

        if regexp_filter:
            IsString().check(regexp_filter)
            parameters["regExpFilter"] = regexp_filter
        if reason:
            IsString().check(reason)
            parameters["reason"] = reason
        if cells:
            IsString().check(cells)
            parameters["networkCellDNs"] = [dn.strip() for dn in cells.split(",")]

        self.store.get(alias).execute_procedure("snapshot", parameters, timeout, output_file_name=target_file_name)

    def collect_im_snapshot(self, target_file_name, timeout=60, alias="default"):
        """Collect InfoModel snapshot.

        :param string target_file_name: target InfoModel snapshot filename.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(target_file_name)
        self.store.get(alias).execute_procedure("imSnapshot", {}, timeout, output_file_name=target_file_name)

    def collect_infomodel_log_from_current_session(self, target_file_name, timeout=60, alias="default"):
        """Collect InfoModel log from current session. Function will also save .ims2 disconnection logs to a given dir.

        :param string target_file_name: target InfoModel snapshot filename.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(target_file_name)
        self.store.get(alias).execute_infomodel_request("imsFromCurrentSession", {}, timeout, output_file_name=target_file_name)
        save_disconnect_logs(target_file_name)

    def reset_site(self, timeout=300, alias="default"):
        """Preform site reset procedure.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        self.store.get(alias).execute_procedure("siteReset", {}, timeout)

    def reset_rat(self, rat, timeout=60, alias="default"):
        """Preform RAT reset procedure.

        :param string rat: RAT name (LTE, WCDMA or GSM).
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        IsOneOf("LTE", "WCDMA", "GSM").check(rat)
        self.store.get(alias).execute_procedure("ratReset", {"type": rat}, timeout)

    def enable_ethernet_port_security(self, timeout=60, alias="default"):
        """Enable ethernet port security.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        self.store.get(alias).execute_procedure("changeEthernetPortSecurity", {"enableEthernetPortSec": True}, timeout)

    def disable_ethernet_port_security(self, timeout=60, alias="default"):
        """Disable ethernet port security.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        self.store.get(alias).execute_procedure("changeEthernetPortSecurity", {"enableEthernetPortSec": False}, timeout)

    def get_mrbts_state(self, timeout=10, alias="default"):
        """Get MRBTS state.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: string
        :return: MRBTS state
        """
        timeout = timestr_to_secs(timeout)
        return self.store.get(alias).execute_infomodel_request("mrbtsMState", {}, timeout)

    def get_bts_info(self, timeout=10, alias="default"):
        """Get BTS info.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: string
        :return: BTS info
        """
        timeout = timestr_to_secs(timeout)
        response = self.store.get(alias).execute_customer_procedure("getBtsInformation", {}, timeout)
        return response["requestMessage"]

    def lock(self, dist_name, timeout=30, alias="default"):
        """
        Lock RMOD or cell or site
        https://onion.wroclaw.nsn-rdnet.net/branches/master/cli-docs/tutorial-lock.html

        :param string dist_name: Object to lock
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        :return: Oeration response
        """
        timeout = timestr_to_secs(timeout)
        return self.store.get(alias).execute_procedure("lock", {"distName": dist_name}, timeout)

    def unlock(self, dist_name, timeout=30, alias="default"):
        """
        Unlock RMOD or cell or site
        https://onion.wroclaw.nsn-rdnet.net/branches/master/cli-docs/tutorial-unlock.html

        :param string dist_name: Object to unlock
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        :return: Oeration response
        """
        timeout = timestr_to_secs(timeout)
        return self.store.get(alias).execute_procedure("unlock", {"distName": dist_name}, timeout)

    def reset_bbpool(self, bbpool_array, timeout=60, alias='default'):
        """Perform bbpoolReset procedure
        :param list bbpool_array: Array of bbpools dist_names to be reset, i.e.:
        ["MRBTS-1/MNL-1/MNLENT-1/BBADM-1/BBPOOL-1", "MRBTS-1/MNL-1/MNLENT-1/BBADM-1/BBPOOL-2"]
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        return self.store.get(alias).execute_procedure("bbPoolReset", {"id": bbpool_array}, timeout)
